func padRight(s string, l int) string {
	if len(s) >= l {
		return s[:l]
	}
	return s + strings.Repeat(" ", l-len(s))
}

func parseIncome(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		s = "0"
	}
	// s contains digits only
	n, err := decimal.NewFromString(s)
	if err != nil {
		// fallback
		n = decimal.NewFromInt(0)
	}
	// implied 2 decimal places
	return decimal.New(n.IntPart(), -2)
}

func truncToScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func storePic9v99(d decimal.Decimal) decimal.Decimal {
	// truncate to 2, keep low order? But values fit.
	// For safety implement truncation and modulo 10^(7+2) ??? But 9(7)V99 means 7 integer digits max.
	// High-order truncation: keep low order digits.
	d = d.Truncate(2)
	// Determine modulus: 10^(7+2) = 10^9 for scaled integer
	// Actually overflow handling: keep low-order digits that fit.
	// Extract scaled integer
	scaled := d.Shift(2) // integer
	// modulus = 10^9
	mod := decimal.NewFromInt(1).Shift(9) // 10^9
	// For positive numbers, low-order keep = scaled % mod
	// Need sign handling
	sign := scaled.Sign()
	if sign < 0 {
		scaled = scaled.Abs()
	}
	// if scaled >= mod, keep remainder
	if scaled.Cmp(mod) >= 0 {
		scaled = scaled.Mod(mod)
		if sign < 0 {
			scaled = scaled.Neg()
		}
		d = scaled.Shift(-2)
	}
	return d
}

