		} else if len(fracStr) > decPlaces {
			fracStr = fracStr[:decPlaces]
		}
	}
	// overflow: keep low-order integer digits
	if len(intStr) > intPlaceCount {
		intStr = intStr[len(intStr)-intPlaceCount:]
	}
	// left pad intStr with zeros to intPlaceCount
	if len(intStr) < intPlaceCount {
		intStr = strings.Repeat("0", intPlaceCount-len(intStr)) + intStr
	}
	// Build integer formatted part character by character
	// intPic contains commas and placeholders
	// We need to map placeholders to digits in order
	// Create slice for int part output
	intOut := make([]byte, len(intPic))
	// digit index for integer part
	digitIdx := 0
	for i := 0; i < len(intPic); i++ {
		ch := intPic[i]
		if ch == 'Z' || ch == '9' {
			intOut[i] = intStr[digitIdx]
			digitIdx++
		} else {
			intOut[i] = byte(ch) // comma
		}
	}
	// Apply Z suppression
	// Find last '9' position in intPic (rightmost mandatory digit)
	lastNinePos := -1
	for i := len(intPic) - 1; i >= 0; i-- {
