			lastNinePos = i
			break
		}
	}
	// Suppress leading zeros for Z positions
	// Determine if there is any non-zero digit to left of current placeholder?
	// Standard: scan from left to right; Z positions that are zero and with no non-zero to their left are replaced by space.
	// Commas in suppressed zone become spaces.
	// Implementation: walk integer placeholders left to right, track if significant seen.
