		if ch == 'Z' || ch == '9' {
			d := intOut[i] // '0'..'9'
			if d != '0' {
				significant = true
			}
			if ch == 'Z' && !significant {
				// suppress: digit becomes space
				intOut[i] = ' '
			} else {
				significant = true
			}
		}
	}
	// Now commas: if they are in a region where all digit placeholders to left are suppressed (spaces) and to right not yet significant? Actually COBOL: commas inside suppressed zone become spaces.
	// Simplified: a comma is replaced by space if every placeholder to its left is suppressed (i.e., is space) and also no significant digit to left.
	// Our intOut currently has spaces for suppressed Z. So check.
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == ',' {
			// check if all placeholder positions to left that are not suppressed? Actually if no significant digit has appeared before this comma, it becomes space.
			// Determine if any digit position before i is significant (i.e., intOut contains '1'..'9' or '0' that is mandatory)
			hasSigBefore := false
			for j := 0; j < i; j++ {
				if intPic[j] == 'Z' || intPic[j] == '9' {
					if intOut[j] != ' ' {
						hasSigBefore = true
						break
					}
				}
			}
			// Also need to check if any non-zero after? But standard replaces comma with space if left part is suppressed.
			if !hasSigBefore {
				intOut[i] = ' '
			} else {
				// check if everything after still zero suppression? Actually comma should stay if there is significant after? Already handled.
				// Keep comma.
			}
			// Additional case: if comma is between suppressed digits, already space.
		}
	}
	// Handle special case where integer part is all spaces/zeros -> ensure at least one zero before decimal? The picture has final 9 ensures one digit remains.
	// Our logic already keeps the last 9 as '0' if all zero.

	// Assemble final output
	var result string
	if dotIdx >= 0 {
		result = string(intOut) + "." + fracStr
	} else {
		result = string(intOut)
	}
	// Ensure length equals width (picture length)
	if len(result) != width {
		// pad or truncate (should not happen)
		if len(result) < width {
			result = strings.Repeat(" ", width-len(result)) + result
		} else {
			result = result[len(result)-width:]
		}
	}
	if neg {
		// Not needed for this program, but handle sign: replace leftmost space with '-'
		for i := 0; i < len(result); i++ {
			if result[i] == ' ' {
