			return
		}
		// last line without newline
	}
	// Remove trailing \r\n
	line = strings.TrimRight(line, "\r\n")
	// Pad to 13
	line = padRight(line, 13)
	if err != nil && len(strings.TrimRight(line, " ")) == 0 && err.Error() == "EOF" {
		// Actually if we got data, treat as record
	}
	if len(line) < 13 {
		line = padRight(line, 13)
	}
	// Check for EOF condition: if read error and no data
	if err != nil && len(line) == 13 && strings.TrimSpace(line) == "" {
		// Need to detect real EOF: if underlying error was EOF and line was empty originally
		// We already handled empty line case; if line is padded spaces from empty, it's EOF
		// But if file ended, ReadString returns EOF with data; next call will be empty.
		// So if we are here with data, process it, next call will signal EOF.
		// To avoid infinite loop, we need to know if original read had EOF and line was from EOF.
		// The above handles next call. So continue.
	}
	// If err != nil and we had data, we will process this last record and next call will hit EOF.
	// Determine if this call was actually EOF with no data: handled at top by err and len(line)==0 before pad
	if len(line) == 13 && inputDone {
		return
	}
	// If the original read returned EOF and line was empty, we already returned.
	// Now check if we had EOF error: we still have a record to process; don't mark done yet.
	// Actually need to detect EOF for next iteration: if err != nil, after processing this record, next read will be EOF.
	// So we don't set done here.
	// But if err != nil and the line we processed is the last line, the next READPARA will set done.
	// However if err != nil and line was empty, we returned done.
	// So for non-empty last line with EOF, we should not set done now.
	if err != nil && len(strings.TrimRight(line, "\r\n")) == 0 {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	// Parse record
	recStr := line
	TaxRecVar.TrId = recStr[0:5]
	incomeStr := recStr[5:13]
	TaxRecVar.TrIncome = parseIncome(incomeStr)
	// If this read had EOF, the next read will be EOF; but we have a valid record now.
	// To handle correctly, if err != nil, we keep inputDone false for now, but the buffered reader is at EOF.
	// The next READPARA will attempt to read and get EOF with no data.
	if err != nil {
		// We have consumed last line; next read will be EOF.
		// We leave flag as is, but ensure reader will return EOF next time.
		// No action.
	}
}

func PROCESSPARA() {
	tenThousand := decimal.NewFromInt(10000).Shift(0).Add(decimal.NewFromInt(0))
	// Use decimal constants
