	limit2 := decimal.NewFromInt(40000)
	if TaxRecVar.TrIncome.Cmp(limit1) <= 0 {
		// WS-TAX ROUNDED = TR-INCOME * 0.10
		v := TaxRecVar.TrIncome.Mul(decimal.NewFromFloat(0.10))
		v = v.Round(2)
		WsTax = storePic9v99(v)
	} else {
