			v := TaxRecVar.TrIncome.Sub(limit1).Mul(decimal.NewFromFloat(0.20)).Add(decimal.NewFromInt(1000))
			v = v.Round(2)
			WsTax = storePic9v99(v)
		} else {
			v := TaxRecVar.TrIncome.Sub(limit2).Mul(decimal.NewFromFloat(0.30)).Add(decimal.NewFromInt(7000))
			v = v.Round(2)
			WsTax = storePic9v99(v)
		}
	}
	// WS-NET = TR-INCOME - WS-TAX (truncated)
	WsNet = storePic9v99(TaxRecVar.TrIncome.Sub(WsTax).Truncate(2))
	WsTotalTax = storePic9v99Total(WsTotalTax.Add(WsTax).Truncate(2))
	WsCount = WsCount + 1
	// Keep low 3 digits for count? Use store
	if WsCount > 999 {
