func storePic9v99Total(d decimal.Decimal) decimal.Decimal {
	d = d.Truncate(2)
	scaled := d.Shift(2)
	mod := decimal.NewFromInt(1).Shift(11) // 10^11 for 9(9)V99 => 9+2=11
	if scaled.Cmp(mod) >= 0 || scaled.Cmp(mod.Neg()) <= 0 {
		scaled = scaled.Mod(mod)
		d = scaled.Shift(-2)
	}
	return d
}

